33	/**
34	 * The reader for reading a complete {@link StripedBlockUtil.AlignedStripe}
35	 * which belongs to a single stripe.
36	 * Reading cross multiple strips is not supported in this reader.
37	 */
38	class StatefulStripeReader extends StripeReader {
39	
40	  StatefulStripeReader(AlignedStripe alignedStripe,
41	      ErasureCodingPolicy ecPolicy, LocatedBlock[] targetBlocks,
42	      BlockReaderInfo[] readerInfos, CorruptedBlocks corruptedBlocks,
43	      RawErasureDecoder decoder, DFSStripedInputStream dfsStripedInputStream) {
44	    super(alignedStripe, ecPolicy, targetBlocks, readerInfos,
45	        corruptedBlocks, decoder, dfsStripedInputStream);
46	  }
47	
48	  @Override
49	  void prepareDecodeInputs() {
50	    final ByteBuffer cur;
51	    synchronized (dfsStripedInputStream) {
52	      cur = dfsStripedInputStream.getCurStripeBuf().duplicate();
53	    }
54	
55	    this.decodeInputs = new ECChunk[dataBlkNum + parityBlkNum];
56	    int bufLen = (int) alignedStripe.getSpanInBlock();
57	    int bufOff = (int) alignedStripe.getOffsetInBlock();
58	    for (int i = 0; i < dataBlkNum; i++) {
59	      cur.limit(cur.capacity());
60	      int pos = bufOff % cellSize + cellSize * i;
61	      cur.position(pos);
62	      cur.limit(pos + bufLen);
63	      decodeInputs[i] = new ECChunk(cur.slice(), 0, bufLen);
64	      if (alignedStripe.chunks[i] == null) {
65	        alignedStripe.chunks[i] =
66	            new StripingChunk(decodeInputs[i].getBuffer());
67	      }
68	    }
69	  }
70	
71	  @Override
72	  boolean prepareParityChunk(int index) {
73	    Preconditions.checkState(index >= dataBlkNum
74	        && alignedStripe.chunks[index] == null);
75	    if (readerInfos[index] != null && readerInfos[index].shouldSkip) {
76	      alignedStripe.chunks[index] = new StripingChunk(StripingChunk.MISSING);
77	      // we have failed the block reader before
78	      return false;
79	    }
80	    final int parityIndex = index - dataBlkNum;
81	    ByteBuffer buf = dfsStripedInputStream.getParityBuffer().duplicate();
82	    buf.position(cellSize * parityIndex);
83	    buf.limit(cellSize * parityIndex + (int) alignedStripe.range.spanInBlock);
84	    decodeInputs[index] =
85	        new ECChunk(buf.slice(), 0, (int) alignedStripe.range.spanInBlock);
86	    alignedStripe.chunks[index] =
87	        new StripingChunk(decodeInputs[index].getBuffer());
88	    return true;
89	  }
90	
91	  @Override
92	  void decode() throws IOException {
93	    finalizeDecodeInputs();
94	    decodeAndFillBuffer(false);
95	  }
96	}

