47	/**
48	 * The reader for reading a complete {@link StripedBlockUtil.AlignedStripe}.
49	 * Note that an {@link StripedBlockUtil.AlignedStripe} may cross multiple
50	 * stripes with cellSize width.
51	 */
52	abstract class StripeReader {
53	
54	  static class ReaderRetryPolicy {
55	    private int fetchEncryptionKeyTimes = 1;
56	    private int fetchTokenTimes = 1;
57	
58	    void refetchEncryptionKey() {
59	      fetchEncryptionKeyTimes--;
60	    }
61	
62	    void refetchToken() {
63	      fetchTokenTimes--;
64	    }
65	
66	    boolean shouldRefetchEncryptionKey() {
67	      return fetchEncryptionKeyTimes > 0;
68	    }
69	
70	    boolean shouldRefetchToken() {
71	      return fetchTokenTimes > 0;
72	    }
73	  }
74	
75	  static class BlockReaderInfo {
76	    final BlockReader reader;
77	    final DatanodeInfo datanode;
78	    /**
79	     * when initializing block readers, their starting offsets are set to the
80	     * same number: the smallest internal block offsets among all the readers.
81	     * This is because it is possible that for some internal blocks we have to
82	     * read "backwards" for decoding purpose. We thus use this offset array to
83	     * track offsets for all the block readers so that we can skip data if
84	     * necessary.
85	     */
86	    long blockReaderOffset;
87	    /**
88	     * We use this field to indicate whether we should use this reader. In case
89	     * we hit any issue with this reader, we set this field to true and avoid
90	     * using it for the next stripe.
91	     */
92	    boolean shouldSkip = false;
93	
94	    BlockReaderInfo(BlockReader reader, DatanodeInfo dn, long offset) {
95	      this.reader = reader;
96	      this.datanode = dn;
97	      this.blockReaderOffset = offset;
98	    }
99	
100	    void setOffset(long offset) {
101	      this.blockReaderOffset = offset;
102	    }
103	
104	    void skip() {
105	      this.shouldSkip = true;
106	    }
107	  }
108	
109	  private final Map<Future<BlockReadStats>, Integer> futures =
110	      new HashMap<>();
111	  protected final AlignedStripe alignedStripe;
112	  private final CompletionService<BlockReadStats> service;
113	  protected final LocatedBlock[] targetBlocks;
114	  protected final CorruptedBlocks corruptedBlocks;
115	  protected final BlockReaderInfo[] readerInfos;
116	  protected final ErasureCodingPolicy ecPolicy;
117	  protected final short dataBlkNum;
118	  protected final short parityBlkNum;
119	  protected final int cellSize;
120	  protected final RawErasureDecoder decoder;
121	  protected final DFSStripedInputStream dfsStripedInputStream;
122	
123	  protected ECChunk[] decodeInputs;
124	
125	  StripeReader(AlignedStripe alignedStripe,
126	      ErasureCodingPolicy ecPolicy, LocatedBlock[] targetBlocks,
127	      BlockReaderInfo[] readerInfos, CorruptedBlocks corruptedBlocks,
128	      RawErasureDecoder decoder,
129	      DFSStripedInputStream dfsStripedInputStream) {
130	    this.alignedStripe = alignedStripe;
131	    this.ecPolicy = ecPolicy;
132	    this.dataBlkNum = (short)ecPolicy.getNumDataUnits();
133	    this.parityBlkNum = (short)ecPolicy.getNumParityUnits();
134	    this.cellSize = ecPolicy.getCellSize();
135	    this.targetBlocks = targetBlocks;
136	    this.readerInfos = readerInfos;
137	    this.corruptedBlocks = corruptedBlocks;
138	    this.decoder = decoder;
139	    this.dfsStripedInputStream = dfsStripedInputStream;
140	
141	    service = new ExecutorCompletionService<>(
142	            dfsStripedInputStream.getStripedReadsThreadPool());
143	  }
144	
145	  /**
146	   * Prepare all the data chunks.
147	   */
148	  abstract void prepareDecodeInputs();
149	
150	  /**
151	   * Prepare the parity chunk and block reader if necessary.
152	   */
153	  abstract boolean prepareParityChunk(int index);
154	
155	  /**
156	   * Decode to get the missing data.
157	   * @throws IOException if the decoder is closed.
158	   */
159	  abstract void decode() throws IOException;
160	
161	  /*
162	   * Default close do nothing.
163	   */
164	  void close() {
165	  }
166	
167	  void updateState4SuccessRead(StripingChunkReadResult result) {
168	    Preconditions.checkArgument(
169	        result.state == StripingChunkReadResult.SUCCESSFUL);
170	    readerInfos[result.index].setOffset(alignedStripe.getOffsetInBlock()
171	        + alignedStripe.getSpanInBlock());
172	  }
173	
174	  private void checkMissingBlocks() throws IOException {
175	    if (alignedStripe.missingChunksNum > parityBlkNum) {
176	      clearFutures();
177	      throw new IOException(alignedStripe.missingChunksNum
178	          + " missing blocks, the stripe is: " + alignedStripe
179	          + "; locatedBlocks is: " + dfsStripedInputStream.getLocatedBlocks());
180	    }
181	  }
182	
183	  /**
184	   * We need decoding. Thus go through all the data chunks and make sure we
185	   * submit read requests for all of them.
186	   */
187	  private void readDataForDecoding() throws IOException {
188	    prepareDecodeInputs();
189	    for (int i = 0; i < dataBlkNum; i++) {
190	      Preconditions.checkNotNull(alignedStripe.chunks[i]);
191	      if (alignedStripe.chunks[i].state == StripingChunk.REQUESTED) {
192	        if (!readChunk(targetBlocks[i], i)) {
193	          alignedStripe.missingChunksNum++;
194	        }
195	      }
196	    }
197	    checkMissingBlocks();
198	  }
199	
200	  void readParityChunks(int num) throws IOException {
201	    for (int i = dataBlkNum, j = 0; i < dataBlkNum + parityBlkNum && j < num;
202	         i++) {
203	      if (alignedStripe.chunks[i] == null) {
204	        if (prepareParityChunk(i) && readChunk(targetBlocks[i], i)) {
205	          j++;
206	        } else {
207	          alignedStripe.missingChunksNum++;
208	        }
209	      }
210	    }
211	    checkMissingBlocks();
212	  }
213	
214	  private ByteBufferStrategy[] getReadStrategies(StripingChunk chunk) {
215	    if (chunk.useByteBuffer()) {
216	      ByteBufferStrategy strategy = new ByteBufferStrategy(
217	          chunk.getByteBuffer(), dfsStripedInputStream.getReadStatistics(),
218	          dfsStripedInputStream.getDFSClient());
219	      return new ByteBufferStrategy[]{strategy};
220	    }
221	
222	    ByteBufferStrategy[] strategies =
223	        new ByteBufferStrategy[chunk.getChunkBuffer().getSlices().size()];
224	    for (int i = 0; i < strategies.length; i++) {
225	      ByteBuffer buffer = chunk.getChunkBuffer().getSlice(i);
226	      strategies[i] = new ByteBufferStrategy(buffer,
227	              dfsStripedInputStream.getReadStatistics(),
228	              dfsStripedInputStream.getDFSClient());
229	    }
230	    return strategies;
231	  }
232	
233	  private int readToBuffer(BlockReader blockReader,
234	      DatanodeInfo currentNode, ByteBufferStrategy strategy,
235	      ExtendedBlock currentBlock) throws IOException {
236	    final int targetLength = strategy.getTargetLength();
237	    int length = 0;
238	    try {
239	      while (length < targetLength) {
240	        int ret = strategy.readFromBlock(blockReader);
241	        if (ret < 0) {
242	          throw new IOException("Unexpected EOS from the reader");
243	        }
244	        length += ret;
245	      }
246	      return length;
247	    } catch (ChecksumException ce) {
248	      DFSClient.LOG.warn("Found Checksum error for "
249	          + currentBlock + " from " + currentNode
250	          + " at " + ce.getPos());
251	      //Clear buffer to make next decode success
252	      strategy.getReadBuffer().clear();
253	      // we want to remember which block replicas we have tried
254	      corruptedBlocks.addCorruptedBlock(currentBlock, currentNode);
255	      throw ce;
256	    } catch (IOException e) {
257	      DFSClient.LOG.warn("Exception while reading from "
258	          + currentBlock + " of " + dfsStripedInputStream.getSrc() + " from "
259	          + currentNode, e);
260	      //Clear buffer to make next decode success
261	      strategy.getReadBuffer().clear();
262	      throw e;
263	    }
264	  }
265	
266	  private Callable<BlockReadStats> readCells(final BlockReader reader,
267	      final DatanodeInfo datanode, final long currentReaderOffset,
268	      final long targetReaderOffset, final ByteBufferStrategy[] strategies,
269	      final ExtendedBlock currentBlock) {
270	    return () -> {
271	      // reader can be null if getBlockReaderWithRetry failed or
272	      // the reader hit exception before
273	      if (reader == null) {
274	        throw new IOException("The BlockReader is null. " +
275	            "The BlockReader creation failed or the reader hit exception.");
276	      }
277	      Preconditions.checkState(currentReaderOffset <= targetReaderOffset);
278	      if (currentReaderOffset < targetReaderOffset) {
279	        long skipped = reader.skip(targetReaderOffset - currentReaderOffset);
280	        Preconditions.checkState(
281	            skipped == targetReaderOffset - currentReaderOffset);
282	      }
283	
284	      int ret = 0;
285	      for (ByteBufferStrategy strategy : strategies) {
286	        int bytesReead = readToBuffer(reader, datanode, strategy, currentBlock);
287	        ret += bytesReead;
288	      }
289	      return new BlockReadStats(ret, reader.isShortCircuit(),
290	          reader.getNetworkDistance());
291	    };
292	  }
293	
294	  boolean readChunk(final LocatedBlock block, int chunkIndex)
295	      throws IOException {
296	    final StripingChunk chunk = alignedStripe.chunks[chunkIndex];
297	    if (block == null) {
298	      chunk.state = StripingChunk.MISSING;
299	      return false;
300	    }
301	
302	    if (readerInfos[chunkIndex] == null) {
303	      if (!dfsStripedInputStream.createBlockReader(block,
304	          alignedStripe.getOffsetInBlock(), targetBlocks,
305	          readerInfos, chunkIndex)) {
306	        chunk.state = StripingChunk.MISSING;
307	        return false;
308	      }
309	    } else if (readerInfos[chunkIndex].shouldSkip) {
310	      chunk.state = StripingChunk.MISSING;
311	      return false;
312	    }
313	
314	    chunk.state = StripingChunk.PENDING;
315	    Callable<BlockReadStats> readCallable =
316	        readCells(readerInfos[chunkIndex].reader,
317	        readerInfos[chunkIndex].datanode,
318	        readerInfos[chunkIndex].blockReaderOffset,
319	        alignedStripe.getOffsetInBlock(), getReadStrategies(chunk),
320	        block.getBlock());
321	
322	    Future<BlockReadStats> request = service.submit(readCallable);
323	    futures.put(request, chunkIndex);
324	    return true;
325	  }
326	
327	  /**
328	   * read the whole stripe. do decoding if necessary
329	   */
330	  void readStripe() throws IOException {
331	    for (int i = 0; i < dataBlkNum; i++) {
332	      if (alignedStripe.chunks[i] != null &&
333	          alignedStripe.chunks[i].state != StripingChunk.ALLZERO) {
334	        if (!readChunk(targetBlocks[i], i)) {
335	          alignedStripe.missingChunksNum++;
336	        }
337	      }
338	    }
339	    // There are missing block locations at this stage. Thus we need to read
340	    // the full stripe and one more parity block.
341	    if (alignedStripe.missingChunksNum > 0) {
342	      checkMissingBlocks();
343	      readDataForDecoding();
344	      // read parity chunks
345	      readParityChunks(alignedStripe.missingChunksNum);
346	    }
347	    // TODO: for a full stripe we can start reading (dataBlkNum + 1) chunks
348	
349	    // Input buffers for potential decode operation, which remains null until
350	    // first read failure
351	    while (!futures.isEmpty()) {
352	      try {
353	        StripingChunkReadResult r = StripedBlockUtil
354	            .getNextCompletedStripedRead(service, futures, 0);
355	        dfsStripedInputStream.updateReadStats(r.getReadStats());
356	        DFSClient.LOG.debug("Read task returned: {}, for stripe {}",
357	            r, alignedStripe);
358	        StripingChunk returnedChunk = alignedStripe.chunks[r.index];
359	        Preconditions.checkNotNull(returnedChunk);
360	        Preconditions.checkState(returnedChunk.state == StripingChunk.PENDING);
361	
362	        if (r.state == StripingChunkReadResult.SUCCESSFUL) {
363	          returnedChunk.state = StripingChunk.FETCHED;
364	          alignedStripe.fetchedChunksNum++;
365	          updateState4SuccessRead(r);
366	          if (alignedStripe.fetchedChunksNum == dataBlkNum) {
367	            clearFutures();
368	            break;
369	          }
370	        } else {
371	          returnedChunk.state = StripingChunk.MISSING;
372	          // close the corresponding reader
373	          dfsStripedInputStream.closeReader(readerInfos[r.index]);
374	
375	          final int missing = alignedStripe.missingChunksNum;
376	          alignedStripe.missingChunksNum++;
377	          checkMissingBlocks();
378	
379	          readDataForDecoding();
380	          readParityChunks(alignedStripe.missingChunksNum - missing);
381	        }
382	      } catch (InterruptedException ie) {
383	        String err = "Read request interrupted";
384	        DFSClient.LOG.error(err);
385	        clearFutures();
386	        // Don't decode if read interrupted
387	        throw new InterruptedIOException(err);
388	      }
389	    }
390	
391	    if (alignedStripe.missingChunksNum > 0) {
392	      decode();
393	    }
394	  }
395	
396	  /**
397	   * Some fetched {@link StripingChunk} might be stored in original application
398	   * buffer instead of prepared decode input buffers. Some others are beyond
399	   * the range of the internal blocks and should correspond to all zero bytes.
400	   * When all pending requests have returned, this method should be called to
401	   * finalize decode input buffers.
402	   */
403	
404	  void finalizeDecodeInputs() {
405	    for (int i = 0; i < alignedStripe.chunks.length; i++) {
406	      final StripingChunk chunk = alignedStripe.chunks[i];
407	      if (chunk != null && chunk.state == StripingChunk.FETCHED) {
408	        if (chunk.useChunkBuffer()) {
409	          chunk.getChunkBuffer().copyTo(decodeInputs[i].getBuffer());
410	        } else {
411	          chunk.getByteBuffer().flip();
412	        }
413	      } else if (chunk != null && chunk.state == StripingChunk.ALLZERO) {
414	        decodeInputs[i].setAllZero(true);
415	      }
416	    }
417	  }
418	
419	  /**
420	   * Decode based on the given input buffers and erasure coding policy.
421	   */
422	  void decodeAndFillBuffer(boolean fillBuffer) throws IOException {
423	    // Step 1: prepare indices and output buffers for missing data units
424	    int[] decodeIndices = prepareErasedIndices();
425	
426	    final int decodeChunkNum = decodeIndices.length;
427	    ECChunk[] outputs = new ECChunk[decodeChunkNum];
428	    for (int i = 0; i < decodeChunkNum; i++) {
429	      outputs[i] = decodeInputs[decodeIndices[i]];
430	      decodeInputs[decodeIndices[i]] = null;
431	    }
432	
433	    long start = Time.monotonicNow();
434	    // Step 2: decode into prepared output buffers
435	    decoder.decode(decodeInputs, decodeIndices, outputs);
436	
437	    // Step 3: fill original application buffer with decoded data
438	    if (fillBuffer) {
439	      for (int i = 0; i < decodeIndices.length; i++) {
440	        int missingBlkIdx = decodeIndices[i];
441	        StripingChunk chunk = alignedStripe.chunks[missingBlkIdx];
442	        if (chunk.state == StripingChunk.MISSING && chunk.useChunkBuffer()) {
443	          chunk.getChunkBuffer().copyFrom(outputs[i].getBuffer());
444	        }
445	      }
446	    }
447	    long end = Time.monotonicNow();
448	    // Decoding time includes CPU time on erasure coding and memory copying of
449	    // decoded data.
450	    dfsStripedInputStream.readStatistics.addErasureCodingDecodingTime(
451	        end - start);
452	  }
453	
454	  /**
455	   * Prepare erased indices.
456	   */
457	  int[] prepareErasedIndices() {
458	    int[] decodeIndices = new int[parityBlkNum];
459	    int pos = 0;
460	    for (int i = 0; i < alignedStripe.chunks.length; i++) {
461	      if (alignedStripe.chunks[i] != null &&
462	          alignedStripe.chunks[i].state == StripingChunk.MISSING){
463	        decodeIndices[pos++] = i;
464	      }
465	    }
466	
467	    int[] erasedIndices = Arrays.copyOf(decodeIndices, pos);
468	    return erasedIndices;
469	  }
470	
471	  void clearFutures() {
472	    for (Future future : futures.keySet()) {
473	      future.cancel(false);
474	    }
475	    futures.clear();
476	  }
477	
478	  boolean useDirectBuffer() {
479	    return decoder.preferDirectBuffer();
480	  }
481	}

